from fastapi import Depends, FastAPI
from fastapi.testclient import TestClient

app = FastAPI()

async def get_current_user() -> dict[str, str]:
    return {"username": "production"}

@app.get("/users/me")
async def read_me(user: dict[str, str] = Depends(get_current_user)) -> dict[str, str]:
    return user

async def override_current_user() -> dict[str, str]:
    return {"username": "test-user"}

def test_read_me_with_override() -> None:
    app.dependency_overrides[get_current_user] = override_current_user
    try:
        response = TestClient(app).get("/users/me")
        assert response.status_code == 200
        assert response.json() == {"username": "test-user"}
    finally:
        app.dependency_overrides.clear()

