from collections.abc import Generator
from fastapi import Depends, FastAPI
from fastapi.testclient import TestClient
from sqlmodel import Field, Session, SQLModel, create_engine, select
from sqlalchemy.pool import StaticPool

class Hero(SQLModel, table=True):
    id: int | None = Field(default=None, primary_key=True)
    name: str

main_engine = create_engine("sqlite://", connect_args={"check_same_thread": False}, poolclass=StaticPool)
SQLModel.metadata.create_all(main_engine)

def get_session() -> Generator[Session, None, None]:
    with Session(main_engine) as session:
        yield session

app = FastAPI()

@app.post("/heroes", response_model=Hero)
def create_hero(hero: Hero, session: Session = Depends(get_session)) -> Hero:
    session.add(hero)
    session.commit()
    session.refresh(hero)
    return hero

@app.get("/heroes", response_model=list[Hero])
def read_heroes(session: Session = Depends(get_session)) -> list[Hero]:
    return list(session.exec(select(Hero)))

def test_create_hero_in_isolated_database() -> None:
    test_engine = create_engine("sqlite://", connect_args={"check_same_thread": False}, poolclass=StaticPool)
    SQLModel.metadata.create_all(test_engine)

    def override_session() -> Generator[Session, None, None]:
        with Session(test_engine) as session:
            yield session

    app.dependency_overrides[get_session] = override_session
    try:
        response = TestClient(app).post("/heroes", json={"name": "Ada"})
        assert response.status_code == 200
        assert response.json() == {"id": 1, "name": "Ada"}
    finally:
        app.dependency_overrides.clear()

from unittest.mock import patch
import uvicorn
from fastapi import FastAPI

app = FastAPI()

@app.get("/debug-info")
async def debug_info() -> dict[str, str]:
    return {"mode": "debug"}

def run_debug_server() -> None:
    uvicorn.run(app, host="127.0.0.1", port=8000)

def test_debug_entrypoint() -> None:
    with patch.object(uvicorn, "run") as mocked_run:
        run_debug_server()
        mocked_run.assert_called_once_with(app, host="127.0.0.1", port=8000)

if __name__ == "__main__":
    run_debug_server()
